package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructSpecializedType_TriageGen1Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testConstructSpecializedType_SameRawClass_ReturnsBaseType() {
        JavaType baseType = typeFactory.constructSimpleType(ArrayList.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertSame("Should return the exact same instance if raw classes match", baseType, result);
    }

    @Test
    public void testConstructSpecializedType_ObjectBase_ReturnsSubclass() {
        JavaType baseType = typeFactory.constructSimpleType(Object.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, String.class);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructSpecializedType_IncompatibleSubclass_ThrowsException() {
        JavaType baseType = typeFactory.constructSimpleType(Integer.class);
        try {
            typeFactory.constructSpecializedType(baseType, String.class);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("not subtype of"));
        }
    }

    @Test
    public void testConstructSpecializedType_NoGenericsInBase_ReturnsSubclass() {
        // baseType is List (raw/no bindings)
        JavaType baseType = typeFactory.constructSimpleType(List.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
        assertTrue(result.getBindings().isEmpty());
    }

    @Test
    public void testConstructSpecializedType_MapShortcut_HashMap() {
        // baseType is Map<String, Integer>
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, HashMap.class);

        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }

    @Test
    public void testConstructSpecializedType_MapShortcut_TreeMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, TreeMap.class);

        assertEquals(TreeMap.class, result.getRawClass());
        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }

    @Test
    public void testConstructSpecializedType_CollectionShortcut_ArrayList() {
        // baseType is Collection<String>
        JavaType baseType = typeFactory.constructCollectionType(Collection.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);

        assertEquals(ArrayList.class, result.getRawClass());
        assertEquals(String.class, result.getContentType().getRawClass());
    }

    @Test
    public void testConstructSpecializedType_CollectionShortcut_HashSet() {
        JavaType baseType = typeFactory.constructCollectionType(Collection.class, Double.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, HashSet.class);

        assertEquals(HashSet.class, result.getRawClass());
        assertEquals(Double.class, result.getContentType().getRawClass());
    }

    @Test
    public void testConstructSpecializedType_EnumSetShortcut() {
        // EnumSet is a special case in the code: if rawBase == EnumSet.class, return baseType
        JavaType baseType = typeFactory.constructCollectionType(EnumSet.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumSet.class);
        // Note: The code says if (rawBase == EnumSet.class) return baseType.
        // Since our baseType raw class is EnumSet, it returns baseType.
        assertSame(baseType, result);
    }

    @Test
    public void testConstructSpecializedType_SubclassNoTypeParameters_ReturnsSimpleType() {
        // baseType is List<String>
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        // subclass is Integer (has 0 type parameters)
        // Note: This will actually fail the isAssignableFrom check first if we pass Integer.
        // Let's use a class that is a subtype of List but has no type parameters (unlikely in real Java, 
        // but we can use a dummy or just check the logic path).
        // In real scenarios, most concrete classes like ArrayList don't have type parameters on the class definition.
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
    }

    @Test
    public void testConstructSpecializedType_InterfaceRefinePath() {
        // This targets the 'if (baseType.isInterface())' branch
        // Using List as base type (interface) and ArrayList as subclass
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);

        assertNotNull(result);
        assertEquals(ArrayList.class, result.getRawClass());
    }

    @Test
    public void testConstructSpecializedType_ComplexRefineFallback() {
        // This targets the 'else' branch of the interface check and the 'if (newType == null)' fallback
        // We need a non-interface, non-container type that requires refinement.
        // Since it's hard to trigger the 'newType == null' naturally without mocking, 
        // we simulate a type that might require the manual binding logic.

        // Using a custom class hierarchy
        class Parent<T> {}
        class Child<T> extends Parent<T> {}

        // Create a base type that is Parent<String>
        JavaType baseType = typeFactory.constructType(new com.fasterxml.jackson.databind.type.TypeReference<Parent<String>>() {});

        // specialize to Child<String>
        JavaType result = typeFactory.constructSpecializedType(baseType, Child.class);

        assertNotNull(result);
        assertEquals(Child.class, result.getRawClass());
    }

    @Test
    public void testConstructSpecializedType_MapShortcut_EnumMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumMap.class);
        // EnumMap requires a specific constructor, but the logic in the method 
        // uses TypeBindings.create which is what we test.
        assertEquals(EnumMap.class, result.getRawClass());
    }
}
